CREATE COLUMN TABLE "TEST_AP"."DLN10" ("DocEntry" INTEGER CS_INT NOT NULL , "LineSeq" INTEGER CS_INT NOT NULL , "AftLineNum" INTEGER CS_INT NOT NULL , "OrderNum" INTEGER CS_INT NOT NULL , "LineType" NVARCHAR(1), "LineText" NCLOB MEMORY THRESHOLD 1000, "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjType" NVARCHAR(20) DEFAULT '15', PRIMARY KEY ("DocEntry", "LineSeq")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "DLN10_SECONDARY" ON "TEST_AP"."DLN10" ( "DocEntry" ASC, "AftLineNum" ASC, "OrderNum" ASC )